    $db=noa_bridge_pdo();$jukebox=nj_assets($db);if($admin){try{foreach($db->query('SELECT song_key,status,context FROM noa_jukebox_uploads ORDER BY sequence') as $u)$uploadStates[$u['song_key']]=$u;}catch(PDOException $e){}}
    $rows=$db->query("SELECT doc_key,kind,payload FROM noa_documents WHERE kind IN ('single','playlist','story'".(($admin&&isset($_GET['qa']))?",'jukebox_qa'":"").") ORDER BY doc_key");
    while($r=$rows->fetch(PDO::FETCH_ASSOC)) {
