        if(!noa_sound_visible($p,$admin))continue;
        if($r['kind']==='playlist')$collections[]=['key'=>$r['doc_key'],'title'=>(string)(($b['confirmedTitle']??'')?:($p['title']??'')),'genre'=>(string)($p['genreId']??'unclassified'),'ep'=>'','act'=>(string)($p['act']??''),'kind'=>'playlist','video'=>'','thumb'=>''];
        $suno=noa_sound_suno($b);$audio=nj_resolve($jukebox,$r['doc_key'],$suno,'audio')?:noa_sound_audio($b,__DIR__);$card=nj_resolve($jukebox,$r['doc_key'],$suno,'cover')?:noa_sound_cover($b);
        if($r['kind']==='playlist'&&!$suno&&!$audio)continue;
