        $title=(string)($b['confirmedTitle']??$p['title']??'');if(trim($title)==='')$title=(string)($p['title']??$r['doc_key']);
        $genre=(string)($p['genreId']??'other');$genres[$genre]=($genres[$genre]??0)+1;
        $songs[]=['audioSha'=>$jukebox[$r['doc_key']]['audio_sha256']??'','audioBytes'=>(int)($jukebox[$r['doc_key']]['audio_bytes']??0),'audioStatus'=>$uploadStates[$r['doc_key']]['status']??($audio?'ready':'audio_pending'),'originalArtist'=>$b['originalArtist']??$b['originalSinger']??'','sunoId'=>$jukebox[$r['doc_key']]['suno_id']??'','sunoTitle'=>$jukebox[$r['doc_key']]['suno_title']??'','key'=>$r['doc_key'],'title'=>$title,'genre'=>$genre,'video'=>'','suno'=>$suno,'audio'=>$audio,'confirmed'=>!empty($p['confirmed']),'ep'=>(string)($p['ep']??''),'act'=>(string)($p['act']??''),'kind'=>$r['kind'],'lyrics'=>noa_sound_lyrics((string)($b['lyricsBlock']??'')),'cast'=>(string)($b['thumbCast']??''),'thumb'=>$thumb,'tracklist'=>(string)($b['tracklist']??'')];
    }
    foreach(nj_catalog($db) as $key=>$d){if(!str_starts_with($key,'catalog:')||!noa_sound_visible($d,$admin))continue;$b=$d['body']??[];$suno=noa_sound_suno($b);$audio=nj_resolve($jukebox,$key,$suno,'audio');$card=nj_resolve($jukebox,$key,$suno,'cover');$g=(string)($d['genreId']??'unclassified');$genres[$g]=($genres[$g]??0)+1;$songs[]=['audioSha'=>$jukebox[$key]['audio_sha256']??'','audioBytes'=>(int)($jukebox[$key]['audio_bytes']??0),'key'=>$key,'title'=>(string)$d['title'],'genre'=>$g,'video'=>'','suno'=>$suno,'sunoId'=>$jukebox[$key]['suno_id']??'','sunoTitle'=>$jukebox[$key]['suno_title']??'','audio'=>$audio,'audioStatus'=>$uploadStates[$key]['status']??($audio?'ready':'audio_pending'),'originalArtist'=>'','confirmed'=>false,'ep'=>(string)($d['ep']??''),'act'=>'','kind'=>'story','lyrics'=>noa_sound_lyrics((string)($b['lyricsBlock']??'')),'cast'=>(string)($b['thumbCast']??''),'thumb'=>$card,'tracklist'=>''];}
