<div class="grid" id="songs"><?php foreach($songs as $song):?><article class="song" data-key="<?=noa_music_e($song['key'])?>" data-jukebox-key="<?=noa_music_e($song['key'])?>" data-jukebox-status="<?=noa_music_e($song['audioStatus'])?>" data-original-artist="<?=noa_music_e($song['originalArtist'])?>" data-title="<?=noa_music_e($song['title'])?>" data-ep="<?=noa_music_e($song['ep'])?>" data-genre="<?=noa_music_e($song['genre'])?>" data-audio="<?=noa_music_e($song['audio'])?>" data-audio-sha="<?=noa_music_e($song['audioSha']??'')?>" data-audio-bytes="<?=(int)($song['audioBytes']??0)?>"><button class="song-select" type="button" aria-label="<?=noa_music_e($song['title'].' 곡 정보')?>"><?php if($song['thumb']):?><img src="<?=noa_music_e($song['thumb'])?>" alt="" loading="lazy" width="56" height="56" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><?php endif;?><span class="cover" <?=$song['thumb']?'hidden':''?> aria-hidden="true">♫</span><span class="info"><strong><?=noa_music_e(($song['ep']?'EP.'.$song['ep'].' · ':($song['act']?'ACT.'.$song['act'].' · ':'')).$song['title'])?></strong><small><?=noa_music_e(str_replace('-',' ',strtoupper($song['genre'])))?> · <?=$song['audio']?'저장된 음원':'Suno 공유 · 음원 파일 연결 필요'?></small></span></button><div class="jukebox-actions"><?php if($song['audio']):?><button class="sound-play noa-icon-button" type="button" aria-label="<?=noa_music_e($song['title'].' 최적화 MP3 재생')?>"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="m8 5 11 7-11 7V5Z"/></svg></button><?php if($admin&&nj_resolve($jukebox,$song['key'],$song['suno'],'audio')):?><a class="jukebox-download noa-icon-button" download href="/noa-app/jukebox/download.php?key=<?=rawurlencode($song['key'])?>" aria-label="<?=noa_music_e($song['title'].' 최적화 MP3 다운로드')?>"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/></svg></a><?php endif;?><?php elseif($admin):?><?php if(in_array($song['audioStatus'],['queued','retrying','analyzing','processing','verifying'],true)):?><button class="jukebox-busy noa-icon-button" disabled aria-label="<?=noa_music_e($song['title'].' 음원 처리 중')?>">◌</button><?php else:?><button class="sound-upload noa-icon-button" type="button" aria-label="<?=noa_music_e($song['title'].' 음원 업로드')?>"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/></svg></button><?php endif;?><?php else:?><span class="jukebox-state">음원 준비 중</span><?php endif;?></div></article><?php endforeach;?></div>
<p class="muted">AI Artist Noa · NOA STUDIO</p>
<script>
const records=<?=json_encode($songs,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR)?>;
const collections=<?=json_encode($collections,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR)?>;
const buttons=[...document.querySelectorAll('.song')],search=document.getElementById('search'),genre=document.getElementById('genre'),type=document.getElementById('type');
let browse=null,filteredQueue=[];const lookup=new Map(records.map(r=>[r.key,r]));let selected=null,player=document.getElementById('sound-player'),ready=true,repeat=false,shuffle=false,pendingAutoplay=false,activeQueue=null;
const status=document.getElementById('player-status');
function requestPlayback(){
 if(!selected?.dataset.audio){status.textContent='Suno 공유 주소만 등록되어 있습니다. 실제 음원 파일을 연결하면 자체 재생할 수 있습니다.';return;}
 pendingAutoplay=true;status.textContent='저장된 음원을 준비하는 중입니다.';
 const request=player.play();if(request?.catch)request.catch(()=>{status.textContent='음원을 재생하지 못했습니다. 재생 버튼과 파일 연결 상태를 확인해 주세요.';});
}

function queue(){const playable=filteredQueue.filter(b=>b.dataset.audio);if(activeQueue)return playable;const playlist=selected&&lookup.get(selected.dataset.key)?.kind==='playlist',sameKind=playable.filter(b=>(lookup.get(b.dataset.key)?.kind==='playlist')===!!playlist);return sameKind.length?sameKind:playable;}
function filter(){
 const q=search.value.trim().toLocaleLowerCase();let rows=records.filter(r=>(!window.NoaTaxonomyFilter||window.NoaTaxonomyFilter(r))&&!((activeQueue&&!activeQueue.includes(r.key))||(type.value&&r.kind!==type.value)||(genre.value&&r.genre!==genre.value)||(q&&!(r.title+' EP.'+r.ep+' ACT.'+r.act).toLocaleLowerCase().includes(q))));
 if(activeQueue)rows.sort((a,b)=>activeQueue.indexOf(a.key)-activeQueue.indexOf(b.key));
 const view=browse?browse.apply(rows,!!activeQueue):{visible:rows,queue:rows,stage:'songs'},visible=new Set(view.visible.map(r=>r.key));
 filteredQueue=view.queue.map(r=>buttons.find(b=>b.dataset.key===r.key)).filter(Boolean);
 buttons.forEach(b=>{b.hidden=!visible.has(b.dataset.key);b.style.order=activeQueue?String(activeQueue.indexOf(b.dataset.key)):'';});
 document.getElementById('songs').hidden=view.stage!=='songs';document.getElementById('result-count').textContent=view.stage==='songs'?view.queue.length+'개 항목 · 재생 대기열 '+queue().length+'개':'';
}
function resetQueue(){activeQueue=null;filter()}search.addEventListener('input',resetQueue);genre.addEventListener('change',resetQueue);type.addEventListener('change',resetQueue);const params=new URLSearchParams(location.search);if([...genre.options].some(o=>o.value===params.get('genre')))genre.value=params.get('genre');if([...type.options].some(o=>o.value===params.get('type')))type.value=params.get('type');filter();
function select(b,autoplay){
 if(selected===b&&ready){if(autoplay)requestPlayback();return;}
 selected=b;pendingAutoplay=autoplay;const r=lookup.get(b.dataset.key);document.querySelector('.player').hidden=false;document.querySelector('.noa-transport').hidden=!r.audio;document.querySelector('[aria-label="곡 상세"]').hidden=false;if(browse)filter();buttons.forEach(x=>x.classList.toggle('selected',x===b));
 document.getElementById('now-title').textContent=r.title;document.getElementById('dock-title').textContent=r.title;document.getElementById('now-genre').textContent=r.genre.replaceAll('-',' ').toUpperCase();
 document.getElementById('detail-title').textContent=(r.ep?'EP.'+r.ep+' · ':r.act?'ACT.'+r.act+' · ':'')+r.title;
 document.getElementById('detail-cast').textContent=({female:'노아 · 여성 솔로',male:'노엘 · 남성 솔로',duet:'노아 & 노엘 · 남녀 듀엣'})[r.cast]||'캐릭터 정보 미등록';
 document.getElementById('cast-noa').hidden=!['female','duet'].includes(r.cast);document.getElementById('cast-noel').hidden=!['male','duet'].includes(r.cast);
 document.getElementById('lyrics-label').textContent=r.kind==='playlist'?'ACT 곡 구성':'가사';document.getElementById('lyrics').textContent=(r.kind==='playlist'?r.tracklist:r.lyrics)||'등록된 내용이 없습니다.';
 const members=r.kind==='playlist'?[...r.tracklist.matchAll(/^\s*(?:[0-9]{1,2}:[0-9]{2}(?::[0-9]{2})?\s+)?EP[.\s]*([0-9]{1,3})\b/gm)].map(m=>'single:'+r.genre+':'+m[1].padStart(2,'0')):[];const ordered=[...new Set(members)].filter(key=>lookup.has(key));const actButton=document.getElementById('act-play');actButton.hidden=ordered.length===0;actButton.onclick=()=>{activeQueue=ordered;genre.value=r.genre;type.value='single';search.value='';filter();const first=queue()[0];if(first)select(first,true)};
 const watch=document.getElementById('watch');watch.hidden=!r.suno;if(r.suno)watch.href=r.suno;
 player.pause();
 if(!r.audio){player.removeAttribute('src');player.load();status.textContent='Suno 공유 주소만 등록되어 있습니다. 실제 음원 파일 연결이 필요합니다.';return;}
 player.src=r.audio;player.load();
 try{sessionStorage.setItem('noa-last-song',r.key)}catch{}
 status.textContent='저장된 음원 · 추가 인코딩 없이 재생합니다.';
 if(autoplay)requestPlayback();
}

function move(direction,ended=false){const q=queue();if(!q.length)return;let i=q.indexOf(selected);if(ended&&repeat&&selected?.dataset.audio){select(selected,true);return}if(shuffle&&q.length>1){const other=q.filter(b=>b!==selected);select(other[Math.floor(Math.random()*other.length)],true);return}if(i<0)i=direction>0?-1:0;let n=i+direction;if(ended&&n>=q.length)return;select(q[(n+q.length)%q.length],true)}
function restorePosition(key){try{const p=JSON.parse(sessionStorage.getItem('noa-playback-position')||'null');return p?.key===key&&Number.isFinite(p.seconds)?Math.max(0,p.seconds):0}catch{return 0}}
document.getElementById('dock-more').onclick=e=>{const bar=document.querySelector('.noa-transport');const expanded=bar.dataset.expanded!=='true';bar.dataset.expanded=String(expanded);e.currentTarget.setAttribute('aria-expanded',String(expanded));};
document.getElementById('pause-play').onclick=()=>{if(!player.paused){pendingAutoplay=false;player.pause();}else requestPlayback();};
document.getElementById('seek').oninput=e=>{if(Number.isFinite(player.duration)&&player.duration>0)player.currentTime=player.duration*Number(e.target.value)/1000;};
document.getElementById('volume').oninput=e=>{player.volume=Number(e.target.value)/100;};player.volume=.7;
const clock=s=>Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0');
player.addEventListener('loadedmetadata',()=>{const p=restorePosition(selected?.dataset.key);if(p>0&&p<player.duration)player.currentTime=p;});
player.addEventListener('timeupdate',()=>{const seconds=player.currentTime,duration=player.duration;if(duration>0){document.getElementById('seek').value=String(Math.round(1000*seconds/duration));document.getElementById('seek-clock').textContent=clock(seconds)+' / '+clock(duration);}try{if(seconds>0)sessionStorage.setItem('noa-playback-position',JSON.stringify({key:selected.dataset.key,seconds}));}catch{}});
for(const event of ['playing','pause','waiting','error'])player.addEventListener(event,()=>{if(!lookup.get(selected?.dataset.key)?.audio)return;const playing=event==='playing';if(playing)window.dispatchEvent(new CustomEvent('noa-media-activity',{detail:{type:'audio',key:selected.dataset.key}}));document.getElementById('pause-play').setAttribute('aria-pressed',String(playing));document.getElementById('pause-play').setAttribute('aria-label',playing?'일시정지':'재생');document.getElementById('pause-play').innerHTML='<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="'+(playing?'M8 5v14M16 5v14':'m8 5 11 7-11 7V5Z')+'"/></svg>';status.textContent=({playing:'저장된 음원 재생 중',pause:'일시정지',waiting:'음원을 불러오는 중입니다.',error:'음원 파일을 재생할 수 없습니다. 파일 형식과 접근 권한을 확인해 주세요.'})[event];});
player.addEventListener('ended',()=>move(1,true));
window.addEventListener('noa-background',()=>{pendingAutoplay=false;player.pause();});
buttons.forEach(b=>{b.querySelector('.song-select').addEventListener('click',()=>select(b,false));b.addEventListener('click',e=>{if(e.target.closest('.sound-play'))select(b,true);});});document.getElementById('previous').onclick=()=>move(-1);document.getElementById('next').onclick=()=>move(1);
for(const id of ['repeat','shuffle'])document.getElementById(id).onclick=e=>{if(id==='repeat')repeat=!repeat;else shuffle=!shuffle;e.currentTarget.setAttribute('aria-pressed',String(id==='repeat'?repeat:shuffle))};
window.addEventListener('noa-jukebox-ready',e=>{const d=e.detail,r=lookup.get(d.key),b=buttons.find(b=>b.dataset.key===d.key);if(r&&b){r.audio=d.audio;b.dataset.audio=d.audio;filter();if(selected===b){selected=null;select(b,false);}}});
let saved='';try{saved=sessionStorage.getItem('noa-last-song')||''}catch{}const first=buttons.find(b=>b.dataset.key===new URLSearchParams(location.search).get('track'))||buttons.find(b=>b.dataset.key===saved&&!b.hidden);if(first)select(first,false);
window.addEventListener('DOMContentLoaded',()=>{browse=window.NoaBrowse.mount({host:document.getElementById('music-browse'),rows:[...new Map([...collections,...records].map(r=>[r.key,r])).values()],onChange:filter,search,genre,type});if(first)browse.reveal(lookup.get(first.dataset.key));filter();const personal=document.getElementById('my-playlists');const showPersonal=()=>personal.hidden=location.hash!=='#my-playlists';showPersonal();window.addEventListener('hashchange',showPersonal);});
if('serviceWorker' in navigator)navigator.serviceWorker.register('/noa-sw.js').catch(()=>{});
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;document.getElementById('install').hidden=false});document.getElementById('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;document.getElementById('install').hidden=true}};
</script><script src="/noa-playlists.js?v=20261021-sound1" defer></script><script src="/noa-taxonomy-browse.js?v=2" defer></script><?php if($admin):?><script src="/noa-app/jukebox/upload-transport.js?v=2" defer></script><script src="/noa-app/jukebox/upload.js?v=15" defer></script><?php endif;?><?php if($admin&&isset($_GET['qa'])):?><output id="jukebox-qa-signal" aria-live="polite">검증 전용 · 재생 대기</output><script>(()=>{const audio=document.getElementById('sound-player'),out=document.getElementById('jukebox-qa-signal');let ctx,analyser,data;audio.addEventListener('play',()=>{try{if(!ctx){ctx=new AudioContext();analyser=ctx.createAnalyser();analyser.fftSize=2048;data=new Float32Array(analyser.fftSize);ctx.createMediaElementSource(audio).connect(analyser);analyser.connect(ctx.destination);}ctx.resume();}catch{out.textContent='출력 신호 측정 불가';}});setInterval(()=>{if(!analyser||audio.paused)return;analyser.getFloatTimeDomainData(data);const rms=Math.sqrt(data.reduce((a,x)=>a+x*x,0)/data.length);out.textContent='검증 전용 · '+(rms>.00001?'오디오 출력 신호 확인':'무음 구간')+' · RMS '+rms.toFixed(6)+' · '+audio.currentTime.toFixed(1)+'초';},500);})();</script><?php endif;?></main></body></html>
